enum DynType implements EnumWithLabel {
  repost('转发'),
  reply('评论'),
  like('赞');

  @override
  final String label;
  const DynType(this.label);
}

mixin DynReplyLocateStateMixin<T extends StatefulWidget>
    on CommonDynPageMixin<T> {
  DynReplyLocateMixin get dynReplyLocateCtr =>
      controller as DynReplyLocateMixin;

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    dynReplyLocateCtr.didChangeDependencies(context);
  }

  @override
  Widget buildReply(BuildContext context, int index, ReplyInfo item) {
    final child = super.buildReply(context, index, item);
    final controller = dynReplyLocateCtr;
    if (item.id == controller.targetRootRpId) {
      final targetSecondRpId = controller.targetSecondRpId;
      if (targetSecondRpId == null) {
        return controller.colorAnimWrapper(theme.colorScheme, child);
      } else {
        controller
          ..targetRootRpId = null
          ..targetSecondRpId = null;
        WidgetsBinding.instance.addPostFrameCallback(
          (_) => replyReply(context, item, targetSecondRpId),
        );
      }
    }
    return child;
  }
}

abstract class CommonDynPageState<T extends StatefulWidget> extends State<T>
    with
        SingleTickerProviderStateMixin<T>,
        BaseFabMixin,
        FabMixin,
        ReplyFooterMixin<T, MainListReply>,
        CommonDynPageMixin<T> {}

abstract class CommonDynPageMultiState<T extends StatefulWidget>
    extends State<T>
    with
        TickerProviderStateMixin<T>,
        BaseFabMixin,
        FabMixin,
        ReplyFooterMixin<T, MainListReply>,
        CommonDynPageMixin<T> {
  late final TabController tabController;

  @override
  void initState() {
    super.initState();
    tabController = TabController(
      length: DynType.values.length,
      initialIndex: DynType.reply.index,
      vsync: this,
    );
  }

  @override
  void dispose() {
    tabController.dispose();
    super.dispose();
  }
}

mixin CommonDynPageMixin<T extends StatefulWidget>
    on
        State<T>,
        TickerProvider,
        BaseFabMixin<T>,
        FabMixin<T>,
        ReplyFooterMixin<T, MainListReply> {
  @override
  CommonDynController get controller;
  bool get isArticle => false;

  bool get horizontalPreview => !isPortrait && controller.horizontalPreview;

  dynamic get arguments;

  late ThemeData theme;
  @override
  ColorScheme get colorScheme => theme.colorScheme;
  late bool isPortrait;
  late double maxWidth;
  late double maxHeight;

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final size = MediaQuery.sizeOf(context);
    theme = Theme.of(context);
    maxWidth = size.width;
    maxHeight = size.height;
    isPortrait = size.isPortrait;
  }

  @override
  bool onNotification(UserScrollNotification notification) {
    if (notification.metrics.axisDirection == .down) {
      return super.onNotification(notification);
    }
    return false;
  }

  Widget buildReplyHeader() {
    return SliverPinnedHeader(
      backgroundColor: theme.colorScheme.surface,
      child: Padding(
        padding: const .fromLTRB(12, 6, 12, 6),
        child: Obx(() {
          final sortType = controller.sortType.value;
          final count = controller.count.value;
          return YoutubeCommentSort(
            selected: sortType,
            totalCount: count,
            onSelect: (type) {
              if (sortType != type && sortType != ReplySortType.select) {
                controller.queryBySort();
              }
            },
          );
        }),
      ),
    );
  }

  Widget replyList(LoadingState<List<ReplyInfo>?> loadingState) {
    switch (loadingState) {
      case Loading():
        return const SliverPrototypeExtentList(
          prototypeItem: VideoReplySkeleton(),
          delegate: SliverSingleChildDelegate(
            count: 12,
            child: VideoReplySkeleton(),
          ),
        );
      case Success(:final response):
        if (response != null && response.isNotEmpty) {
          var count = response.length + 1;
          final voteCard = controller.voteCard;
          final hasVote = voteCard != null;
          if (hasVote) {
            count++;
          }
          return ArticleSliverList.builder(
            itemCount: count,
            isArticle: isArticle,
            itemBuilder: (context, index) {
              if (hasVote) {
                if (index == 0) {
                  return buildVoteCard(context, theme.colorScheme, voteCard);
                } else {
                  index--;
                }
              }
              if (index == response.length) {
                return buildFooter();
              } else {
                return buildReply(context, index, response[index]);
              }
            },
          );
        }

        final child = httpError(
          errMsg: '还没有评论',
          onReload: controller.onReload,
        );
        if (controller.voteCard case final voteCard?) {
          return SliverMainAxisGroup(
            slivers: [
              SliverToBoxAdapter(
                child: buildVoteCard(context, theme.colorScheme, voteCard),
              ),
              child,
            ],
          );
        }
        return child;
      case Error(:final errMsg):
        return httpError(
          errMsg: errMsg,
          onReload: controller.onReload,
        );
    }
  }

  Widget buildReply(BuildContext context, int index, ReplyInfo item) {
    return ReplyItemGrpc(
      replyItem: item,
      replyLevel: 1,
      replyReply: (item, id) => throttleReplyReply(context, item, id),
      onReply: controller.onReply,
      onDelete: (item, subIndex) => controller.onRemove(index, item, subIndex),
      upMid: controller.upMid,
      onViewImage: hideFab,
      onCheckReply: controller.onCheckReply,
      onToggleTop: (item) => controller.onToggleTop(
        item,
        index,
        controller.oid,
        controller.replyType,
      ),
      youtubeStyle: true,
    );
  }

  Widget httpError({String? errMsg, VoidCallback? onReload}) {
    return HttpError(
      errMsg: errMsg,
      onReload: controller.onReload,
    );
  }

  void throttleReplyReply(BuildContext context, ReplyInfo replyItem, int? id) {
    EasyThrottle.throttle(
      'replyReply',
      const Duration(milliseconds: 500),
      () => replyReply(context, replyItem, id),
    );
  }

  void replyReply(BuildContext context, ReplyInfo replyItem, int? id) {
    Widget replyReplyPage({bool showBackBtn = true}) {
      final child = ViewSafeArea(
        left: showBackBtn,
        right: showBackBtn,
        child: VideoReplyReplyPanel(
          enableSlide: false,
          id: id,
          oid: replyItem.oid.toInt(),
          rpid: replyItem.id.toInt(),
          isVideoDetail: !showBackBtn,
          replyType: controller.replyType,
          firstFloor: replyItem,
          heroTag: arguments?['heroTag'],
          upMid: controller.upMid,
        ),
      );
      if (showBackBtn) {
        return SimpleScaffold(
          appBar: AppBar(
            title: const Text('评论详情'),
            shape: Border(
              bottom: BorderSide(
                color: theme.colorScheme.outline.withValues(alpha: 0.1),
              ),
            ),
          ),
          body: child,
        );
      }
      return child;
    }

    if (!isPortrait) {
      final scaffoldState = MiniScaffold.maybeOf(context);
      if (scaffoldState != null) {
        hideFab();
        scaffoldState.showBottomSheet(
          constraints: const BoxConstraints(),
          (context) => replyReplyPage(showBackBtn: false),
        );
        return;
      }
    }

    Get.to(
      replyReplyPage,
      routeName: 'dynamicDetail-Copy',
      arguments: arguments,
    );
  }

  Widget ratioWidget(double maxWidth) => IconButton(
    tooltip: '页面比例调节',
    onPressed: () => showDialog(
      context: context,
      builder: (context) => Align(
        alignment: Alignment.topRight,
        child: Container(
          margin: const EdgeInsets.only(top: 56, right: 16),
          width: maxWidth / 4,
          height: 32,
          child: Builder(
            builder: (context) => Slider(
              min: 1,
              max: 100,
              value: controller.ratio.first,
              onChanged: (value) {
                if (value >= 10 && value <= 90) {
                  value = value.toPrecision(2);
                  controller.ratio
                    ..[0] = value
                    ..[1] = 100 - value;

                  (context as Element).markNeedsBuild();
                  setState(() {});
                }
              },
              onChangeEnd: (_) => GStorage.setting.put(
                SettingBoxKey.dynamicDetailRatio,
                controller.ratio,
              ),
            ),
          ),
        ),
      ),
    ),
    icon: const Icon(CustomIcons.splitscreen_rotate_90, size: 19),
  );

  FloatingActionButtonLocation get floatingActionButtonLocation =>
      controller.showDynActionBar
      ? const ActionBarLocation()
      : const NoBottomPaddingFabLocation();

  Widget get fabButton => Padding(
    padding: .only(
      right: kFloatingActionButtonMargin + padding.right,
      bottom: kFloatingActionButtonMargin + padding.bottom,
    ),
    child: replyButton,
  );

  Widget get replyButton => FloatingActionButton(
    heroTag: null,
    onPressed: () {
      try {
        feedBack();
        controller.onReply(
          null,
          oid: controller.oid,
          replyType: controller.replyType,
          mentionItem: controller.mentionItem,
        );
      } catch (_) {}
    },
    tooltip: '评论',
    child: const Icon(Icons.reply),
  );
}

