                ),
                onTap: () => _updateBool(
                  () => _skipBottom = !_skipBottom,
                  SettingBoxKey.mergeDanmakuSkipBottom,
                  !_skipBottom,
                ),
              ),
            ],
          ),
          _SectionTitle('显示设置', theme),
          _couiCardGroup(
            context,
            [
              ListTile(
                title: const Text('数量标记位置'),
                subtitle: Text(switch (_markPosition) {
                  0 => '始终隐藏数量标记',
                  2 => '显示在弹幕尾部',
