class SetDisplayMode extends StatefulWidget {
  const SetDisplayMode({super.key});

  @override
  State<SetDisplayMode> createState() => _SetDisplayModeState();
}

class _SetDisplayModeState extends State<SetDisplayMode> {
  List<DisplayMode> modes = <DisplayMode>[];
  DisplayMode? active;
  DisplayMode? preferred;

  Box setting = GStorage.setting;

  @override
  void initState() {
    super.initState();
    init();
  }

  // 获取所有的mode
  Future<void> fetchAll() async {
    preferred = await FlutterDisplayMode.preferred;
    active = await FlutterDisplayMode.active;
    setting.put(SettingBoxKey.displayMode, preferred.toString());
    if (mounted) {
      setState(() {});
    }
  }

  // 初始化mode/手动设置
  Future<void> init() async {
    try {
      modes = await FlutterDisplayMode.supported;
    } on PlatformException catch (e) {
      if (kDebugMode) debugPrint(e.toString());
    }

    final value = setting.get(SettingBoxKey.displayMode);
    if (value != null) {
      preferred = modes.firstWhereOrNull((e) => e.toString() == value);
    }

    preferred ??= DisplayMode.auto;

    FlutterDisplayMode.setPreferredMode(preferred!).whenComplete(() {
      Timer(const Duration(milliseconds: 100), fetchAll);
    });
  }

  @override
  Widget build(BuildContext context) {
    return SimpleScaffold(
      appBar: AppBar(title: const Text('屏幕帧率设置')),
      body: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Padding(
            padding:
                MediaQuery.viewPaddingOf(context).copyWith(top: 0, bottom: 0) +
                const EdgeInsets.only(left: 25, top: 10, bottom: 5),
            child: Text(
              '没有生效？重启app试试',
              style: TextStyle(color: Theme.of(context).colorScheme.outline),
            ),
          ),
          Expanded(
            child: RadioGroup(
              onChanged: (newMode) {
                FlutterDisplayMode.setPreferredMode(newMode!).whenComplete(
                  () => Timer(const Duration(milliseconds: 100), fetchAll),
                );
              },
              groupValue: preferred,
              child: ListView.builder(
                itemCount: modes.length,
                padding: .only(
                  bottom: MediaQuery.viewPaddingOf(context).bottom,
                ),
                itemBuilder: (context, index) {
                  final DisplayMode mode = modes[index];
                  final first = index == 0;
                  final last = index == modes.length - 1;
                  final coui = CouiThemeData.of(context);
                  final borderSide = BorderSide(
                    color: coui.subtleBorderColor,
                    width: 0.75,
                  );
                  return Padding(
                    padding: EdgeInsets.fromLTRB(
                      16,
                      first ? 8 : 0,
                      16,
                      last ? 8 : 0,
                    ),
                    child: DecoratedBox(
                      decoration: BoxDecoration(
                        borderRadius: BorderRadius.vertical(
                          top: first
                              ? const Radius.circular(Coui.card)
                              : Radius.zero,
                          bottom: last
                              ? const Radius.circular(Coui.card)
                              : Radius.zero,
                        ),
                        border: Border(
                          left: borderSide,
                          right: borderSide,
                          top: first ? borderSide : BorderSide.none,
                          bottom: last ? borderSide : BorderSide.none,
                        ),
                      ),
                      child: ClipRRect(
                        borderRadius: BorderRadius.vertical(
                          top: first
                              ? const Radius.circular(Coui.card)
                              : Radius.zero,
                          bottom: last
                              ? const Radius.circular(Coui.card)
                              : Radius.zero,
                        ),
                        child: Material(
                          color: coui.cardColor,
                          child: Column(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              RadioListTile<DisplayMode>(
                                value: mode,
                                title: mode == DisplayMode.auto
                                    ? const Text('自动')
                                    : Text(
                                        '$mode${mode == active ? '  [系统]' : ''}',
                                      ),
                              ),
                              if (!last)
                                Divider(
                                  height: 0.5,
                                  thickness: 0.5,
                                  indent: 16,
                                  endIndent: 16,
                                  color: coui.dividerColor,
                                ),
                            ],
                          ),
                        ),
                      ),
                    ),
                  );
                },
              ),
            ),
          ),
        ],
      ),
    );
  }
}

