        title: isSearch
            ? TextField(
                autofocus: true,
                focusNode: _controller.searchFocusNode,
                controller: _controller.searchController,
                textInputAction: TextInputAction.search,
                textAlignVertical: TextAlignVertical.center,
                decoration: InputDecoration(
                  hintText: '搜索',
                  visualDensity: VisualDensity.standard,
                  border: InputBorder.none,
                  suffixIcon: IconButton(
                    tooltip: '清空',
                    icon: const Icon(Icons.clear, size: 22),
                    onPressed: () {
                      _controller.searchController.clear();
                      _controller.searchFocusNode.requestFocus();
                    },
                  ),
                ),
              )
            : Row(
                spacing: 12,
                children: [
                  NetworkImgLayer(
                    width: 40,
                    height: 40,
                    src: info.mvCover,
                    type: ImageType.avatar,
                  ),
                  Column(
                    mainAxisAlignment: MainAxisAlignment.center,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        info.musicTitle!,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: theme.textTheme.titleMedium,
                      ),
                      Obx(() {
                        final count =
                            _controller.loadingState.value.dataOrNull?.length;
                        return count == null
                            ? const SizedBox.shrink()
                            : Text(
                                '共$count条视频',
                                style: theme.textTheme.labelMedium,
                              );
                      }),
                    ],
                  ),
                ],
              ),
        actions: [
          if (!isSearch) ...[
            IconButton(
              tooltip: '搜索',
              onPressed: () => _controller.isSearchMode.value = true,
              icon: const Icon(Icons.search_outlined),
            ),
            Builder(
              builder: (menuContext) => IconButton(
                tooltip: '排序方式',
                icon: const Icon(Icons.sort),
                onPressed: () async {
                  final value = await showCouiMenu<MusicRecommendOrderType>(
                    context: menuContext,
                    items: MusicRecommendOrderType.values
                        .map(
                          (e) => CouiMenuItem<MusicRecommendOrderType>(
                            label: e.label,
                            value: e,
                            selected: e == _controller.order.value,
                          ),
                        )
                        .toList(),
                  );
                  if (value != null) {
                    _controller
                      ..order.value = value
                      ..applySortAndFilter();
                  }
                },
              ),
            ),
            const SizedBox(width: 10),
          ]
        ],
      );
    });
  }
}

