class _BatteryInfo {
  const _BatteryInfo({
    required this.level,
    required this.state,
  });

  final int level;
  final BatteryState state;

  IconData? get icon => switch (state) {
    BatteryState.charging => Icons.battery_charging_full,
    BatteryState.connectedNotCharging => Icons.power,
    BatteryState.full => Icons.battery_full,
    _ => null,
  };
}

mixin TimeBatteryMixin<T extends StatefulWidget> on State<T> {
  PlPlayerController get plPlayerController;
  late final titleKey = GlobalKey();
  ContextSingleTicker? provider;
  ContextSingleTicker get effectiveProvider => provider ??= ContextSingleTicker(
    context,
    autoStart: () =>
        plPlayerController.showControls.value &&
        !plPlayerController.controlsLock.value,
  );

  bool get isPortrait;
  bool get isFullScreen;
  bool get horizontalScreen;

  Timer? _clock;
  RxString now = ''.obs;

  static final _format = DateFormat('HH:mm');

  @override
  void dispose() {
    stopBatteryInfoListener();
    stopClock();
    super.dispose();
  }

  void startClock() {
    if (!_showCurrTime) return;
    if (_clock == null) {
      now.value = _format.format(DateTime.now());
      _clock ??= Timer.periodic(const Duration(seconds: 1), (Timer t) {
        if (!mounted) {
          stopClock();
          return;
        }
        now.value = _format.format(DateTime.now());
      });
    }
  }

  void stopClock() {
    _clock?.cancel();
    _clock = null;
  }

  bool _showCurrTime = false;
  void showCurrTimeIfNeeded(bool isFullScreen) {
    _showCurrTime = !isPortrait && (isFullScreen || !horizontalScreen);
    if (!_showCurrTime) {
      stopClock();
      stopBatteryInfoListener();
    }
  }

  late final _battery = Battery();
  late final Rxn<_BatteryInfo> _batteryInfo = Rxn<_BatteryInfo>();
  StreamSubscription<BatteryState>? _batterySubscription;
  late final _showBatteryLevel = Pref.showBatteryLevel;

  Future<void> _updateBatteryInfo([BatteryState? state]) async {
    try {
      final batteryState = state ?? await _battery.batteryState;
      final batteryLevel = await _battery.batteryLevel;
      if (mounted && _showCurrTime && _showBatteryLevel) {
        _batteryInfo.value = _BatteryInfo(
          level: batteryLevel,
          state: batteryState,
        );
      }
    } catch (_) {}
  }

  bool _startBatteryInfoListenerIfNeeded() {
    if (!_showCurrTime || !_showBatteryLevel) {
      stopBatteryInfoListener();
      return false;
    }
    if (_batterySubscription != null) return false;
    _batterySubscription = _battery.onBatteryStateChanged.listen(
      (state) {
        if (mounted) {
          _updateBatteryInfo(state);
        }
      },
      onError: (_) {},
    );
    _updateBatteryInfo();
    return true;
  }

  void stopBatteryInfoListener() {
    _batterySubscription?.cancel();
    _batterySubscription = null;
  }

  void updateBatteryInfoIfNeeded() {
    if (!_showCurrTime || !_showBatteryLevel) {
      stopBatteryInfoListener();
      return;
    }
    if (_startBatteryInfoListenerIfNeeded()) return;
    if (_batteryInfo.value == null) {
      _updateBatteryInfo();
      return;
    }
    EasyThrottle.throttle(
      'updateBatteryInfo$hashCode',
      const Duration(seconds: 30),
      _updateBatteryInfo,
    );
  }

  Widget _batteryStatusIcon(_BatteryInfo batteryInfo) {
    final icon = batteryInfo.icon;
    if (icon == null) {
      return const SizedBox.shrink();
    }
    return Padding(
      padding: const EdgeInsets.only(right: 3),
      child: Icon(
        icon,
        color: Colors.white,
        size: 13,
      ),
    );
  }

  List<Widget>? get timeBatteryWidgets {
    if (_showCurrTime) {
      return [
        if (_showBatteryLevel) ...[
          Obx(
            () {
              final batteryInfo = _batteryInfo.value;
              if (batteryInfo == null) {
                return const SizedBox.shrink();
              }
              return Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  _batteryStatusIcon(batteryInfo),
                  Text(
                    '${batteryInfo.level}%',
                    style: const TextStyle(
                      color: Colors.white,
                      fontSize: 13,
                    ),
                  ),
                ],
              );
            },
          ),
          const SizedBox(width: 10),
        ],
        Obx(
          () => Text(
            now.value,
            style: const TextStyle(
              color: Colors.white,
              fontSize: 13,
            ),
          ),
        ),
      ];
    }
    return null;
  }
}

class HeaderControl extends StatefulWidget {
  const HeaderControl({
    required this.isPortrait,
    required this.controller,
    required this.videoDetailCtr,
    required this.heroTag,
    super.key,
  });

  final bool isPortrait;
  final PlPlayerController controller;
  final VideoDetailController videoDetailCtr;
  final String heroTag;

  @override
  State<HeaderControl> createState() => HeaderControlState();

  static Future<bool> likeDanmaku(VideoDanmaku extra, int cid) async {
    if (!Accounts.main.isLogin) {
      SmartDialog.showToast('请先登录');
      return false;
    }
    final isLike = !extra.isLike;
    final res = await DanmakuHttp.danmakuLike(
      isLike: isLike,
      cid: cid,
      id: extra.id,
    );
    if (res.isSuccess) {
      extra.isLike = isLike;
      if (isLike) {
        extra.like++;
      } else {
        extra.like--;
      }
      SmartDialog.showToast('${isLike ? '' : '取消'}点赞成功');
      return true;
    } else {
      res.toast();
      if (res case Error(:final code)) {
        if (code == 65006) {
          extra.isLike = true;
          return true;
        }
        if (code == 65004) {
          extra.isLike = false;
          return true;
        }
      }
      return false;
    }
  }

  static Future<bool> deleteDanmaku(int id, int cid) async {
    final res = await DanmakuHttp.danmakuRecall(
      cid: cid,
      id: id,
    );
    if (res.isSuccess) {
      SmartDialog.showToast('删除成功');
      return true;
    } else {
      res.toast();
      return false;
    }
  }

  static Future<void> reportDanmaku(
    BuildContext context, {
    required VideoDanmaku extra,
    required PlPlayerController ctr,
  }) {
    if (Accounts.main.isLogin) {
      return autoWrapReportDialog(
        context,
        mid: () => int.parse(extra.mid),
        ReportOptions.danmakuReport,
        withContent: ReportOptions.danmakuReportCheck,
        contentRequired: ReportOptions.danmakuReportCheck,
        (reasonType, reasonDesc, banUid) {
          if (banUid) {
            final filter = ctr.filters;
            if (filter.dmUid.add(extra.mid)) {
              filter.count++;
              GStorage.localCache.put(LocalCacheKey.danmakuFilterRules, filter);
            }
            DanmakuFilterHttp.danmakuFilterAdd(filter: extra.mid, type: 2);
          }
          return DanmakuHttp.danmakuReport(
            reason: reasonType,
            cid: ctr.cid!,
            id: extra.id,
            content: reasonDesc,
          );
        },
      );
    } else {
      return SmartDialog.showToast('请先登录');
    }
  }

  static Future<void> reportLiveDanmaku(
    BuildContext context, {
    required int roomId,
    required String msg,
    required LiveDanmaku extra,
  }) {
    if (Accounts.main.isLogin) {
      return autoWrapReportDialog(
        context,
        ReportOptions.liveDanmakuReport,
        withContent: ReportOptions.liveDanmakuReportCheck,
        contentRequired: ReportOptions.liveDanmakuReportCheck,
        (reasonType, reasonDesc, banUid) {
          // if (banUid) {
          //   final filter = ctr.filters;
          //   if (filter.dmUid.add(extra.mid)) {
          //     filter.count++;
          //     GStorage.localCache.put(
          //       LocalCacheKey.danmakuFilterRules,
          //       filter,
          //     );
          //   }
          //   DanmakuFilterHttp.danmakuFilterAdd(
          //     filter: extra.mid,
          //     type: 2,
          //   );
          // }
          return LiveHttp.liveDmReport(
            roomId: roomId,
            mid: extra.mid,
            msg: msg,
            reason: ReportOptions.liveDanmakuReport['']![reasonType]!,
            reasonId: reasonType,
            dmType: extra.dmType,
            idStr: extra.id,
            ts: extra.ts,
            sign: extra.ct,
          );
        },
      );
    } else {
      return SmartDialog.showToast('请先登录');
    }
  }
}

