class AudioPage extends StatefulWidget {
  const AudioPage({super.key});

  @override
  State<AudioPage> createState() => _AudioPageState();

  static Future<void>? toAudioPage({
    int? id,
    required int oid,
    List<int>? subId,
    required int itemType,
    required PlaylistSource from,
    String? heroTag,
    Duration? start,
    String? audioUrl,
    int? extraId,
  }) {
    heroTag ??= Utils.makeHeroTag(oid);
    return Get.toNamed(
      '/audio',
      arguments: {
        'id': ?id,
        'oid': oid,
        'subId': ?subId,
        'from': from,
        'itemType': itemType,
        'heroTag': heroTag,
        'start': ?start,
        'audioUrl': ?audioUrl,
        'extraId': ?extraId,
      },
    );
  }
}

