                  'title': '稍后再看',
                  'count': _baseCtr.counts[LaterViewType.all.index],
                },
              );
            },
            icon: const Icon(Icons.search),
          ),
          Builder(
            key: _sortKey,
            builder: (context) {
              final value = currCtr().asc.value;
              return Tooltip(
                message: '排序',
                child: InkWell(
                  borderRadius: Coui.cardRadius,
                  onTap: () async {
                    final selected = await showCouiMenu<bool>(
                      context: context,
                      items: [
                        CouiMenuItem<bool>(
                          label: '最近添加',
                          value: false,
                          selected: !value,
                        ),
                        CouiMenuItem<bool>(
                          label: '最早添加',
                          value: true,
                          selected: value,
                        ),
                      ],
                    );
                    if (selected != null) {
                      currCtr()
                        ..asc.value = selected
                        ..onReload();
                    }
                  },
                  child: Padding(
                    padding: const .symmetric(horizontal: 12, vertical: 6),
                    child: Text.rich(
                      style: TextStyle(fontSize: 14, height: 1, color: color),
                      strutStyle: const StrutStyle(
                        leading: 0,
                        height: 1,
                        fontSize: 14,
                      ),
                      TextSpan(
                        children: [
                          TextSpan(text: value ? '最早添加' : '最近添加'),
                          WidgetSpan(
                            alignment: .middle,
                            child: Icon(
                              size: 14,
                              MdiIcons.unfoldMoreHorizontal,
                              color: color,
                            ),
                          ),
                        ],
                        style: TextStyle(color: color),
                      ),
                    ),
                  ),
                ),
              );
            },
          ),
          Builder(
            builder: (menuContext) => Tooltip(
              message: '清空',
              child: InkWell(
                borderRadius: Coui.cardRadius,
                onTap: () => showCouiMenu(
                  context: menuContext,
                  items: [
                    CouiMenuItem(
                      label: '清空失效',
                      onTap: () => currCtr().toViewClear(context, 1),
                    ),
                    CouiMenuItem(
                      label: '清空看完',
                      onTap: () => currCtr().toViewClear(context, 2),
                    ),
                    CouiMenuItem(
                      label: '清空全部',
                      onTap: () => currCtr().toViewClear(context),
                    ),
                  ],
                ),
                child: Padding(
                  padding: const .symmetric(horizontal: 12, vertical: 6),
                  child: Text.rich(
                    style: TextStyle(fontSize: 14, height: 1, color: color),
                    strutStyle: const StrutStyle(
                      leading: 0,
                      height: 1,
                      fontSize: 14,
                    ),
                    TextSpan(
                      children: [
                        const TextSpan(text: '清空'),
                        WidgetSpan(
                          alignment: .middle,
                          child: Icon(
                            size: 14,
                            MdiIcons.unfoldMoreHorizontal,
                            color: color,
                          ),
                        ),
                      ],
                      style: TextStyle(color: color),
                    ),
                  ),
                ),
              ),
            ),
          ),
          const SizedBox(width: 8),
        ],
      ),
    );
  }
