class FavSearchPage extends StatefulWidget {
  const FavSearchPage({super.key});

  @override
  State<FavSearchPage> createState() => _FavSearchPageState();
}

class _FavSearchPageState
    extends
        CommonSearchPageState<FavSearchPage, FavDetailData, FavDetailItemModel>
    with GridMixin {
  @override
  final FavSearchController controller = Get.put(
    FavSearchController(),
    tag: Utils.generateRandomString(8),
  );

  @override
  List<Widget>? get multiSelectActions {
    final btnStyle = TextButton.styleFrom(visualDensity: .compact);
    final textStyle = TextStyle(
      color: ColorScheme.of(context).onSurfaceVariant,
    );
    return [
      TextButton(
        style: btnStyle,
        onPressed: () => RequestUtils.onCopyOrMove<FavDetailItemModel>(
          context: context,
          isCopy: true,
          ctr: controller,
          mediaId: controller.mediaId,
          mid: Accounts.main.mid,
        ),
        child: Text('复制', style: textStyle),
      ),
      TextButton(
        style: btnStyle,
        onPressed: () => RequestUtils.onCopyOrMove<FavDetailItemModel>(
          context: context,
          isCopy: false,
          ctr: controller,
          mediaId: controller.mediaId,
          mid: Accounts.main.mid,
        ),
        child: Text('移动', style: textStyle),
      ),
    ];
  }

  @override
  List<Widget>? get extraActions => [
    Obx(
      () {
        final currentOrder = controller.order.value;
        return Builder(
          builder: (menuContext) => IconButton(
            icon: const Icon(Icons.sort),
            tooltip: '排序方式',
            onPressed: () async {
              final value = await showCouiMenu<FavOrderType>(
                context: menuContext,
                items: FavOrderType.values
                    .map(
                      (e) => CouiMenuItem<FavOrderType>(
                        label: e.label,
                        value: e,
                        selected: e == currentOrder,
                      ),
                    )
                    .toList(),
              );
              if (value != null) {
                controller
                  ..order.value = value
                  ..onReload();
              }
            },
          ),
        );
      },
    ),
  ];

  @override
  Widget buildList(List<FavDetailItemModel> list) {
    return SliverGrid.builder(
      gridDelegate: gridDelegate,
      itemBuilder: (context, index) {
        if (index == list.length - 1) {
          controller.onLoadMore();
        }
        final item = list[index];
        return FavVideoCardH(
          item: item,
          index: index,
          ctr: controller,
        );
      },
      itemCount: list.length,
    );
  }
}

