            // if (_userController.hasGuard)
            //   CouiMenuItem(
            //     label: '大航海舰队',
            //     icon: Icons.anchor,
            //     onTap: () => MemberGuard.toMemberGuard(
            //       mid: _userController.mid,
            //       name: _userController.username ?? '',
            //       count: _userController.guardCount,
