  InlineSpan _buildMsg(double devicePixelRatio, DanmakuMsg obj) {
    final uemote = obj.uemote;
    if (uemote != null) {
      // "room_{{room_id}}_{{int}}", "official_{{int}}" or "upower_[{{emote}}]"
      const upowerDefaultPx = 162.0;
      late final double width;
      late final double height;
      if (uemote.isUpower) {
        width = upowerDefaultPx / devicePixelRatio;
        height = upowerDefaultPx / devicePixelRatio;
      } else if (uemote.isOfficial) {
        width = uemote.width / devicePixelRatio * 1.25;
        height = uemote.height / devicePixelRatio * 1.25;
      } else {
        width = uemote.width / devicePixelRatio;
        height = uemote.height / devicePixelRatio;
      }
      return WidgetSpan(
        child: NetworkImgLayer(
          src: uemote.url,
          type: .emote,
          width: width,
          height: height,
        ),
      );
    }
    final emots = obj.emots;
    if (emots != null) {
      RegExp regExp = RegExp(emots.keys.map(RegExp.escape).join('|'));
      final List<InlineSpan> spanChildren = <InlineSpan>[];
      obj.text.splitMapJoin(
        regExp,
        onMatch: (match) {
          final key = match[0]!;
          final emote = emots[key]!;
          spanChildren.add(
            WidgetSpan(
              child: NetworkImgLayer(
                src: emote.url,
                type: .emote,
                width: emote.width,
                height: emote.height,
              ),
            ),
          );
          return '';
        },
        onNonMatch: (String nonMatchStr) {
          spanChildren.add(
            TextSpan(
              text: nonMatchStr,
              style: const TextStyle(
                color: Colors.white,
                fontSize: 14,
              ),
            ),
          );
          return '';
        },
      );
      return TextSpan(children: spanChildren);
    } else {
      return TextSpan(
        text: obj.text,
        style: const TextStyle(
          color: Colors.white,
          fontSize: 14,
        ),
      );
    }
  }

  void _showMsgMenu(
    BuildContext context,
    BuildContext itemContext,
    TapUpDetails details,
    DanmakuMsg item,
  ) {
    final dx = details.globalPosition.dx;
    final renderBox = itemContext.findRenderObject() as RenderBox;
    final dy =
        details.globalPosition.dy -
        details.localPosition.dy +
        renderBox.size.height -
        4; // padding
    final autoScroll =
        liveRoomController.autoScroll &&
        !liveRoomController.disableAutoScroll.value;
    if (autoScroll) {
      liveRoomController.autoScroll = false;
    }
    showCouiMenu<void>(
      context: context,
      offset: Offset(dx, dy),
      items: [
        CouiMenuItem<void>(
          label: item.name,
          enabled: false,
        ),
        const CouiMenuDivider<void>(),
        CouiMenuItem<void>(
          label: '复制弹幕信息',
          onTap: () => Utils.copyText(Utils.jsonEncoder.convert(item.toJson())),
        ),
        CouiMenuItem<void>(
          label: '去TA的个人空间',
          onTap: () => Get.toNamed('/member?mid=${item.extra.mid}'),
        ),
        if (liveRoomController.isLogin) ...[
          CouiMenuItem<void>(
            label: '@TA',
            onTap: () => liveRoomController.onAtUser(item),
          ),
          CouiMenuItem<void>(
            label: '屏蔽发送者',
            onTap: () async {
              final res = await LiveHttp.liveShieldUser(
                uid: item.extra.mid,
                roomid: liveRoomController.roomId,
                type: 1,
              );
              if (res.isSuccess) {
                SmartDialog.showToast('屏蔽成功');
              } else {
                res.toast();
              }
            },
          ),
          CouiMenuItem<void>(
            label: '举报选中弹幕',
            isDestructive: true,
            onTap: () => HeaderControl.reportLiveDanmaku(
              context,
              roomId: liveRoomController.roomId,
              msg: item.text,
              extra: item.extra,
            ),
          ),
        ],
      ],
    ).whenComplete(() {
      if (autoScroll && context.mounted) {
        liveRoomController
          ..autoScroll = true
          ..scrollToBottom();
      }
    });
  }
}

